const upsertProviderMapping = `-- name: UpsertProviderMapping :one
INSERT INTO provider_mappings (workspace_id, provider, kind, local_id, external_id, created_at)
VALUES (?, ?, ?, ?, ?, ?)
ON CONFLICT (workspace_id, provider, kind, local_id) DO UPDATE SET external_id = excluded.external_id
RETURNING id, workspace_id, provider, kind, local_id, external_id, created_at
`

type UpsertProviderMappingParams struct {
	WorkspaceID int64
	Provider    string
	Kind        string
	LocalID     int64
	ExternalID  string
	CreatedAt   time.Time
}

func (q *Queries) UpsertProviderMapping(ctx context.Context, arg UpsertProviderMappingParams) (ProviderMapping, error) {
	row := q.db.QueryRowContext(ctx, upsertProviderMapping,
		arg.WorkspaceID,
		arg.Provider,
		arg.Kind,
		arg.LocalID,
		arg.ExternalID,
		arg.CreatedAt,
	)
	var i ProviderMapping
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Provider,
		&i.Kind,
		&i.LocalID,
		&i.ExternalID,
		&i.CreatedAt,
	)
	return i, err
}
